'use strict';
const STORE='aio-prototype-parent-child-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const staffProfiles={
 pm:{name:'Minh',title:'PM điều phối',avatar:'parent',provider:'Claude',effort:'High',description:'Giữ mục tiêu, chia việc, điều phối các đội và hỏi anh tại các gate.',rule:'Không tự mở rộng phạm vi. Mọi quyết định của Owner phải được ghi vào hồ sơ.'},
 product:{name:'An',title:'Product / BA',avatar:'product',provider:'Claude',effort:'High',description:'Làm rõ vấn đề, đề xuất sản phẩm và đặc tả quy tắc nghiệp vụ.',rule:'Đề xuất độc lập từ mục tiêu trước khi đối chiếu giải pháp trong spec.'},
 lead:{name:'Khoa',title:'Tech Lead',avatar:'scout',provider:'Codex',effort:'High',description:'Chọn phương án kỹ thuật, xác định phụ thuộc và hợp đồng bàn giao.',rule:'Kiểm tra hiện trạng trước khi đề xuất; ghi rõ ảnh hưởng và rủi ro.'},
 designer:{name:'Linh',title:'Designer',avatar:'shaper',provider:'Claude',effort:'Medium',description:'Thiết kế hành trình người dùng và bàn giao trải nghiệm cho Developer.',rule:'Thiết kế phải gắn mục tiêu và tiêu chí chấp nhận, có trạng thái lỗi/rỗng.'},
 dev:{name:'Nam',title:'Developer',avatar:'implementer',provider:'Codex',effort:'High',description:'Viết kiểm thử, xây dựng và sửa đúng phần việc được giao.',rule:'Viết test chứng minh hành vi chưa đạt trước khi sửa; sửa xong test phải đạt.'},
 tester:{name:'Mai',title:'Tester',avatar:'verifier',provider:'Claude',effort:'High',description:'Kiểm thử độc lập, hồi quy và lưu bằng chứng đạt hoặc chưa đạt.',rule:'Không có bằng chứng thì chưa PASS. Không tự nghiệm thu phần code mình viết.'},
 reviewer:{name:'Vy',title:'Code Reviewer',avatar:'reviewer',provider:'Codex',effort:'High',description:'Review độc lập mục tiêu, chất lượng thay đổi và tác động chéo.',rule:'Phát hiện phải có tình huống cụ thể. Tách lỗi cần sửa với đề xuất tùy chọn.'},
 release:{name:'Quân',title:'Release Engineer',avatar:'macro',provider:'Claude',effort:'Medium',description:'Tích hợp, quản lý staging, phát hành và kiểm tra sau triển khai.',rule:'Chỉ phát hành đúng phiên bản được Owner duyệt. Ghi rõ cách quay lui.'},
 secretary:{name:'Nhi',title:'Thư ký',avatar:'secretary',provider:'Claude',effort:'Medium',description:'Tiếp nhận đề bài, hỗ trợ cấu hình và chuyển thông tin đến đúng đội.',rule:'Không đoán người nhận. Giữ liên kết từ yêu cầu ban đầu tới phản hồi của đội.'}
};
const seedTasks=[
{id:'A',title:'Thống nhất dữ liệu & quy tắc nhắc',description:'Chốt múi giờ, trạng thái đã học, quyền bật/tắt và giao diện bàn giao giữa các phần.',team:'coord',deps:[],owner:'lead',status:'draft',criteria:['Thống nhất cách lưu múi giờ và lịch nhắc.','Xác định khi nào một người được nhận hoặc bỏ qua nhắc học.','Có hợp đồng dữ liệu để hai đội triển khai độc lập.']},
{id:'B',title:'Cho phép người dùng thiết lập lịch',description:'Màn hình chọn giờ, bật/tắt nhắc học và phản hồi lưu cấu hình.',team:'experience',deps:['A'],owner:'dev',status:'draft',criteria:['Bật/tắt và lưu giờ nhắc được.','Hiển thị theo đúng múi giờ đã thống nhất.','Có trạng thái đang lưu, thành công và lỗi.']},
{id:'C',title:'Xác định đúng người & gửi nhắc học',description:'Lập lịch gửi qua thông báo trong ứng dụng theo phạm vi của ví dụ.',team:'delivery',deps:['A'],owner:'dev',status:'draft',criteria:['Chỉ gửi cho người bật nhắc và chưa học trong ngày.','Không gửi trùng cùng một kỳ nhắc.','Kiểm thử đúng lịch và múi giờ.']},
{id:'D',title:'Theo dõi lần gửi & xử lý gửi lỗi',description:'Lưu kết quả, kiểm soát thử lại và hỗ trợ truy vết việc gửi.',team:'delivery',deps:['C'],owner:'dev',status:'draft',criteria:['Có kết quả mỗi lần gửi và nguyên nhân thất bại.','Thử lại không làm gửi trùng.','Có tín hiệu để người vận hành biết bất thường.']},
{id:'E',title:'Tích hợp & nghiệm thu hành trình nhắc học',description:'Kiểm tra từ cài lịch đến nhận thông báo trên bản tích hợp trước khi trình Owner.',team:'coord',deps:['B','C','D'],owner:'tester',status:'draft',criteria:['Chạy hành trình người dùng từ cấu hình tới nhận nhắc.','Các task được tích hợp đúng phiên bản.','Có báo cáo PASS/FAIL và điều còn tồn đọng để Owner xem.']}
];
const teams={coord:{title:'Đội điều phối & tích hợp',short:'Điều phối',color:'#6b746d',roles:['pm','product','lead','tester','release'],work:'A · E',purpose:'Giữ mục tiêu tổng, hợp đồng dùng chung và nghiệm thu cả hành trình.'},experience:{title:'Đội trải nghiệm',short:'Trải nghiệm',color:'#8e5bd6',roles:['pm','designer','dev','tester'],work:'B',purpose:'Bàn giao màn hình thiết lập lịch nhắc dùng được.'},delivery:{title:'Đội gửi nhắc',short:'Gửi nhắc',color:'#3b6fb6',roles:['pm','dev','tester','reviewer'],work:'C · D',purpose:'Gửi đúng người, đúng lúc và theo dõi được kết quả.'}};
const seedWorkflow=[{id:'wf1',name:'Nhận đề bài & làm rõ mục tiêu',role:'PM + Product / BA',type:'work'},{id:'wf2',name:'G1 · Chốt sản phẩm & phạm vi',role:'Owner · báo cáo đề xuất sản phẩm',type:'gate'},{id:'wf3',name:'Phân rã task & lập kế hoạch đội',role:'Tech Lead + Tester + PM',type:'work'},{id:'wf4',name:'G2 · Chốt kế hoạch & quyền tự chạy',role:'Owner · báo cáo kế hoạch',type:'gate'},{id:'wf5',name:'Triển khai theo task đủ điều kiện',role:'Developer · test trước khi sửa',type:'work'},{id:'wf6',name:'Kiểm thử & review độc lập',role:'Tester + Code Reviewer',type:'work'},{id:'wf7',name:'Tích hợp & tạo báo cáo nghiệm thu',role:'Release Engineer + Product',type:'report'},{id:'wf8',name:'G3 · Nghiệm thu & cho phép phát hành',role:'Owner · báo cáo đúng phiên bản',type:'gate'},{id:'wf9',name:'Phát hành & theo dõi kết quả',role:'Release Engineer + Product',type:'work'}];
function initial(){return {version:1,approved:false,teamsStarted:false,released:false,releaseApproved:false,revision:1,simulationRound:0,tasks:structuredClone(seedTasks),roles:structuredClone(staffProfiles),workflow:structuredClone(seedWorkflow),workflowVersion:1,workflowDirty:false,extraReports:[],decisions:[],customWork:null,messages:{pm:[{from:'agent',text:'Em đã cùng Product và Tech Lead phân rã đề bài thành 5 task.\n\nB và C có thể chạy song song sau khi A chốt hợp đồng dữ liệu. C và D cùng một đội để giữ context gửi nhắc.\n\nAnh xem bản kế hoạch ở G2 trước nhé. Chưa đội nào bắt đầu code trong ví dụ này.',doc:true}],secretary:[{from:'agent',text:'Chào anh. Anh có thể giao đề bài mới, chỉnh role hoặc xây workflow tại đây. Em sẽ giúp xác định project và PM phù hợp.\n\nĐây là bản mẫu: các phản hồi dùng kịch bản có sẵn, chưa gửi tới agent thực tế.'}]}}}
let state;try{const saved=JSON.parse(localStorage.getItem(STORE));state=saved?.version===1&&Array.isArray(saved.tasks)&&saved.roles&&saved.messages?saved:initial()}catch{state=initial()}
let screen='project',projectTab='tasks',taskView='list',chatClosed=innerWidth<=1000,previousFocus=null,dragId=null;
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));const n=document.querySelector('#saved-label');n.textContent='Đã lưu thay đổi bản mẫu';n.classList.add('save-flash');setTimeout(()=>{n.textContent='Bản mẫu lưu trên trình duyệt';n.classList.remove('save-flash')},1600)}catch{toast('Trình duyệt không cho lưu; thay đổi chỉ giữ trong lần mở này.')}}
function toast(t){const n=document.createElement('div');n.className='toast';n.textContent=t;document.querySelector('#toasts').append(n);setTimeout(()=>n.remove(),3300)}
function av(role,st='working',cls=''){const p=state.roles[role]||state.roles.pm;return `<span class="avatar ${cls}" style="--role:${ROLES[p.avatar]?.color||'#2f6f5e'}">${avatarSvg(p.avatar,st)}</span>`}
function desk(role,st='idle',team='coord'){const p=(state.assignmentRoles||state.roles)[role]||state.roles[role];return `<button class="desk ${st}" data-role="${role}" data-team="${team}" title="${esc(p.name+' · '+p.title)}" aria-label="Xem ${esc(p.title)} của ${esc(teams[team].short)}">${st==='working'?'<span class="bubble typing"><span></span><span></span><span></span></span>':st==='waiting'?'<span class="bubble">chờ anh</span>':st==='done'?'<span class="bubble">✓</span>':''}<div class="seat">${avatarSvg(p.avatar,st)}<span class="status-pin"></span></div><div class="desk-top"><div class="mug"></div><div class="laptop"></div></div><div class="nameplate" style="--role:${ROLES[p.avatar]?.color}"><i></i>${esc(role==='pm'?'PM · '+p.name:p.title)}</div><div class="model-tag">${esc(p.provider)} · ${esc(p.effort)}</div></button>`}
const statusNames={draft:'Đề xuất',ready:'Sẵn sàng',working:'Đang làm',blocked:'Chờ phụ thuộc',done:'Hoàn thành',waiting:'Chờ anh',idle:'Chưa bắt đầu'};
function badge(status,label){return `<span class="status ${esc(status)}">${esc(label||statusNames[status]||status)}</span>`}
const pendingGate=()=>state.tasks.every(t=>t.status==='done')&&!state.releaseApproved?'G3':!state.approved?'G2':null;
function countDone(){return state.tasks.filter(t=>t.status==='done').length}
function title(){return state.customWork?.title||'Nhắc người dùng học mỗi ngày'}
function pageHead(eyebrow,heading,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${heading}</h1><p class="page-sub">${sub}</p></div>${action}</div>`}
function setScreen(next){screen=next;document.querySelector('.sidebar').classList.remove('mobile-open');render();window.scrollTo({top:0,behavior:'instant'})}
function render(){const headings={project:['Lingo','Công việc'],overview:['Công ty','Tổng quan'],secretary:['Công ty','Thư ký'],teams:['Lingo','Các đội thực hiện'],roles:['Thư viện','Nhân sự & role'],workflows:['Thư viện','Workflow'],gates:['Việc của anh','Chờ quyết định'],reports:['Lingo','Báo cáo & quyết định']};const h=headings[screen]||headings.project;document.querySelector('#breadcrumb').innerHTML=`<span>${h[0]}</span><span>/</span><b>${h[1]}</b>`;document.querySelectorAll('.nav[data-screen]').forEach(n=>n.classList.toggle('active',n.dataset.screen===screen||(n.dataset.screen==='project'&&screen==='teams')));document.querySelector('#gate-count').textContent=pendingGate()?'1':'0';document.querySelector('#side-team-count').textContent=Object.keys(teams).length;const renderers={project:renderProject,overview:renderOverview,secretary:renderSecretary,teams:renderTeams,roles:renderRoles,workflows:renderWorkflow,gates:renderGates,reports:renderReports};document.querySelector('#content').innerHTML=renderers[screen]();document.querySelector('.workspace-layout').classList.toggle('chat-closed',chatClosed);renderChat()}
function officeHero(){const memberState=state.approved?'working':'waiting';return `<div class="office-hero"><div class="office-intro"><div class="eyebrow">WORKSPACE CHA · ĐIỀU PHỐI</div><h2>Một mục tiêu.<br>Các đội cùng tiến tới.</h2><p>PM giữ bức tranh tổng. Mỗi đội nhận phần việc rõ ràng<br>và bàn giao lại kết quả có thể kiểm chứng.</p><div class="members">${['pm','product','lead','tester'].map(r=>av(r)).join('')}<span>PM · Product · Tech Lead · Tester</span></div></div><div class="office-scene">${desk('pm',memberState)}${desk('product','done')}${desk('lead',memberState)}</div></div>`}
function gateBanner(){const g=pendingGate();if(g)return `<div class="gate-card"><div class="gate-icon">◇</div><div><h3>${g==='G2'?'G2 · Anh chốt kế hoạch trước khi các đội bắt đầu':'G3 · Bản tích hợp đã sẵn sàng để anh nghiệm thu'}</h3><p>${g==='G2'?`${state.tasks.length} task · 3 đội dự kiến · B và C có thể chạy song song sau A.`:'Đã có kết quả mô phỏng của các task. Xem báo cáo và quyền phát hành riêng.'}</p></div><button class="button small" data-action="${g==='G2'?'review-plan':'review-release'}">${g==='G2'?'Xem & chốt kế hoạch':'Xem báo cáo nghiệm thu'} ↗</button></div>`;return `<div class="note-box" style="margin-bottom:18px"><b style="color:var(--accent)">✓ ${state.released?'Bản minh họa đã phát hành':'Kế hoạch đã được duyệt trong bản mẫu'}</b> · ${state.released?'Chuyển sang theo dõi kết quả; không có triển khai thật.':'Các đội chỉ nhận task khi phụ thuộc đã hoàn thành. Mô phỏng một lượt để xem cách phối hợp.'}</div>`}
function phaseStrip(){const done=countDone()===state.tasks.length;return `<div class="phase-strip"><span class="done"><b>01</b> · Mục tiêu</span><span class="${!state.approved?'current':'done'}"><b>02</b> · Chia việc</span><span class="${state.approved&&!done?'current':done?'done':''}"><b>03</b> · Thực hiện</span><span class="${done?'current':''}"><b>04</b> · Nghiệm thu</span><span class="${state.released?'done':''}"><b>05</b> · Phát hành</span></div>`}
function renderProject(){if(state.customWork)return renderNewBrief();return pageHead('LINGO / CÔNG VIỆC CHA',esc(title()),'Từ một đề bài chung đến các phần việc rõ ràng, có đội chịu trách nhiệm.',`<button class="button small" data-action="edit-brief">Sửa đề bài</button>`)+`<div class="brief card"><span class="owner-mini">H</span><div><span class="brief-label">Đề bài của anh</span><p class="brief-quote">“Tôi muốn người dùng được nhắc học mỗi ngày, có thể chọn giờ<br class="desktop-br"> và không bị nhắc nữa nếu hôm đó đã học.”</p><div class="brief-meta"><span>Phạm vi ví dụ: thông báo trong ứng dụng</span><span>G1 đã chốt trong kịch bản mẫu</span></div></div></div>`+gateBanner()+officeHero()+`<div class="metric-row"><div class="metric"><span>Task đã phân rã</span><strong>${state.tasks.length.toString().padStart(2,'0')}</strong><small>có tiêu chí đạt</small></div><div class="metric"><span>Đội thực hiện</span><strong>03</strong><small>${state.teamsStarted?'đã lập trong bản mẫu':'đề xuất'}</small></div><div class="metric"><span>Đã hoàn thành</span><strong>${countDone().toString().padStart(2,'0')}</strong><small>/ ${state.tasks.length} task</small></div><div class="metric"><span>Chờ anh</span><strong>${pendingGate()?'01':'00'}</strong><small>${pendingGate()||'không có gate'}</small></div></div>`+phaseStrip()+`<div class="tabs" role="tablist" aria-label="Nội dung công việc">${[['tasks','Cây công việc'],['teams','Đội ngũ'],['context','Context & quyết định']].map(([id,label])=>`<button role="tab" aria-selected="${projectTab===id}" class="tab ${projectTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>`+(projectTab==='tasks'?renderTaskSection():projectTab==='teams'?`<div class="section-title"><h2>Ba đội, một PM tổng điều phối</h2></div>${teamCards()}`:renderContext())+`<p class="sample-note">Bản mẫu tương tác · tiến độ, nhân sự và bằng chứng là dữ liệu minh họa. Không gửi lệnh tới Orca, không chạy code hoặc sửa project thật.</p>`}
function taskRows(){return state.tasks.map(t=>`<button class="task-row" data-task="${esc(t.id)}"><span class="task-main"><span class="task-id">${esc(t.id)}</span><span><b>${esc(t.title)}</b><small>${esc(t.owner==='tester'?'Tester nghiệm thu':t.owner==='lead'?'Tech Lead chịu trách nhiệm':'Developer → Tester → Reviewer')}</small></span></span><span class="team-label"><i class="team-dot" style="background:${teams[t.team].color}"></i>${teams[t.team].short}</span><span class="dependency">${t.deps.length?'Chờ '+esc(t.deps.join(', ')):'Không phụ thuộc'}</span><span>${badge(t.status)}</span></button>`).join('')}
function renderTaskSection(){return `<div class="section-title"><h2>Các phần việc <small>Mỗi task bàn giao một kết quả rõ ràng</small></h2><div class="seg"><button class="${taskView==='list'?'active':''}" data-taskview="list">Danh sách</button><button class="${taskView==='graph'?'active':''}" data-taskview="graph">Phụ thuộc</button></div></div><div class="card">${taskView==='list'?`<div class="task-head"><span>TASK / KẾT QUẢ CẦN ĐẠT</span><span>ĐỘI PHỤ TRÁCH</span><span>PHỤ THUỘC</span><span>TRẠNG THÁI</span></div>${taskRows()}`:dependencyGraph()}<div class="footer-hint"><span>↳</span> Task không đồng nghĩa với workspace. C và D cùng một đội; A và E do đội điều phối phụ trách.</div></div><div class="simulate-bar"><button class="button small" data-action="add-task">＋ Thêm task đề xuất</button>${state.approved&&!state.released?`<button class="button small primary" data-action="simulate">${state.releaseApproved?'Mô phỏng phát hành':'Mô phỏng một lượt thực hiện'} →</button>`:''}<small>${state.approved?'Thay đổi tiến độ trong bản mẫu, không chạy agent.':'Task/đội chỉ được giao thực hiện sau khi anh chốt G2.'}</small></div>`}
function dependencyGraph(){const coords={A:[32,118],B:[231,32],C:[231,196],D:[433,196],E:[632,118]},colors={done:'var(--accent)',working:'var(--info)',ready:'var(--accent)',draft:'var(--border-strong)',blocked:'var(--border-strong)'};const base=state.tasks.filter(t=>coords[t.id]);return `<div class="dependency-graph"><svg viewBox="0 0 825 345" role="img" aria-label="A mở đường cho B và C chạy song song; C trước D; E chờ B, C và D"><defs><marker id="dep-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" fill="var(--faint)"/></marker></defs>${base.flatMap(t=>t.deps.filter(d=>coords[d]).map(d=>{let[x,y]=coords[d],[tx,ty]=coords[t.id];return `<path d="M${x+162} ${y+43} C${x+187} ${y+43} ${tx-24} ${ty+43} ${tx-2} ${ty+43}" fill="none" stroke="var(--border-strong)" stroke-width="1.5" marker-end="url(#dep-arrow)"/>`})).join('')}${base.map(t=>{const[x,y]=coords[t.id];const lines={A:['Hợp đồng dữ liệu','& quy tắc nhắc'],B:['Thiết lập','lịch nhắc'],C:['Xác định người','& gửi nhắc'],D:['Lịch sử gửi','& thử lại'],E:['Tích hợp','& nghiệm thu']};return `<g class="graph-task" role="button" tabindex="0" data-task="${t.id}" aria-label="Task ${t.id}: ${esc(t.title)}"><rect x="${x}" y="${y}" width="162" height="88" rx="10" fill="var(--surface)" stroke="${colors[t.status]}"/><text x="${x+12}" y="${y+20}" font-size="10" fill="var(--muted)">${t.id} · ${esc(teams[t.team].short)}</text><text x="${x+12}" y="${y+44}" font-size="12" font-weight="600" fill="var(--text)">${lines[t.id][0]}</text><text x="${x+12}" y="${y+62}" font-size="12" font-weight="600" fill="var(--text)">${lines[t.id][1]}</text><text x="${x+12}" y="${y+78}" font-size="9" fill="var(--muted)">${statusNames[t.status]}</text></g>`}).join('')}<text x="230" y="324" font-size="11" fill="var(--muted)">B và C chạy song song sau A · E nghiệm thu kết quả tổng</text></svg>${state.tasks.length>5?'<p class="inline-note">Task bổ sung xem ở chế độ danh sách; sơ đồ này minh họa năm task A–E của kịch bản gốc.</p>':''}</div>`}
function renderContext(){return `<div class="section-title"><h2>Context được giữ cùng công việc</h2></div><div class="split-2"><div class="card info-card"><h3>Mục tiêu đã chọn trong ví dụ</h3><p>Người dùng tự chọn lịch nhắc; hệ thống chỉ nhắc khi họ chưa học và đã bật nhận thông báo.</p><span class="rule-chip">Trong ứng dụng</span><span class="rule-chip">Theo múi giờ</span><span class="rule-chip">Không gửi trùng</span><h3>Ngoài phạm vi ví dụ</h3><p>Email, SMS và cá nhân hóa nội dung bằng AI.</p></div><div class="card info-card"><h3>Phân tách core và project</h3><div class="context-tree"><b>AI Office</b> / role & workflow mẫu<br>↳ <b>Lingo</b> / quy tắc, công cụ, môi trường<br>　↳ <b>Workspace</b> / mục tiêu, task, quyết định</div><p>Các đội dùng chung quyết định tổng, nhưng có session và hồ sơ phần việc riêng.</p></div></div><div class="section-title"><h2>Lịch sử quyết định</h2></div><div class="card timeline">${decisionTimeline()}</div>`}
function decisionTimeline(){return `<div class="timeline-item"><span class="timeline-dot">✓</span><div><b>G1 · Mục tiêu và phạm vi ví dụ</b><p>Dữ liệu mẫu: chọn thông báo trong ứng dụng, chưa làm email/SMS.</p></div></div>`+state.decisions.map(d=>`<div class="timeline-item"><span class="timeline-dot">◇</span><div><b>${esc(d.title)}</b><p>${esc(d.text)}</p></div></div>`).join('')+(!state.decisions.length?'<p class="inline-note">Các lựa chọn anh thực hiện trong mockup sẽ xuất hiện ở đây.</p>':'')}
function teamCards(){return `<div class="teams-grid">${Object.entries(teams).map(([id,t])=>{const assigned=state.tasks.filter(x=>x.team===id),done=assigned.filter(x=>x.status==='done').length;return `<article class="card team-card"><div class="team-top"><div class="space-between"><span class="eyebrow">${id==='coord'?'WORKSPACE CHA':'WORKSPACE CON'}</span>${badge(state.teamsStarted?'working':'draft',state.teamsStarted?'Đội mô phỏng':'Đội dự kiến')}</div><h3>${t.title}</h3><p>${t.purpose}</p></div><div class="team-floor">${t.roles.map(r=>desk(r,!state.teamsStarted?(id==='coord'&&r==='pm'?'waiting':'idle'):assigned.some(x=>x.status==='working')?'working':done===assigned.length&&assigned.length?'done':'idle',id)).join('')}</div><div class="team-bottom"><span>${assigned.map(x=>x.id).join(' · ')} · ${done}/${assigned.length} task xong</span><button class="button small ghost" data-team-open="${id}">Vào đội →</button></div></article>`}).join('')}</div>`}
function renderTeams(){return pageHead('LINGO / WORKSPACE','Đội nhỏ, trách nhiệm rõ.','Một đội điều phối giữ mục tiêu tổng; hai đội chuyên môn nhận những phần có thể bàn giao độc lập.')+`<div class="note-box" style="margin-bottom:20px">${state.teamsStarted?'Các đội đã được lập trong dữ liệu mô phỏng.':'Các đội đang là đề xuất; chưa khởi tạo session hay workspace thực tế.'} Bấm một nhân vật để xem role được gán trong đội.</div>`+teamCards()}
function renderRoles(){return pageHead('THƯ VIỆN DÙNG CHUNG','Nhân sự & cách mỗi người làm việc','Role mẫu được dùng lại giữa các project. Cấu hình đang xem thuộc thư viện bản mẫu.',`<button class="button small" data-action="add-role">＋ Thêm role</button>`)+`<div class="note-box" style="margin-bottom:20px">Mỗi nhân sự trong đội có session riêng. Role mẫu giữ trách nhiệm và quy tắc; kiến thức riêng của project được bổ sung khi gán vào đội.</div><div class="role-grid">${Object.entries(state.roles).map(([id,p])=>`<button class="card role-card" data-role-edit="${esc(id)}">${av(id,'working','lg')}<h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="role-meta"><span>${esc(p.provider)} · ${esc(p.effort)}</span><span>Cấu hình ↗</span></div></button>`).join('')}</div>`}
function renderWorkflow(){return pageHead('THƯ VIỆN DÙNG CHUNG','Workflow phát triển sản phẩm','Từ đề bài lớn → chia task → đội thực hiện → tích hợp và nghiệm thu.',`<button class="button small primary" data-action="save-workflow">Lưu phiên bản mẫu</button>`)+`<div class="note-box" style="margin-bottom:18px"><b>Bản v${state.workflowVersion}${state.workflowDirty?' · có chỉnh sửa chưa lưu':''}</b> · Kéo khối để đổi thứ tự hoặc dùng nút ↑ ↓. Chỉnh ở đây tạo bản mẫu mới; không tự đổi luồng đang áp dụng cho công việc.</div><div class="card workflow"><div class="workflow-toolbar"><span class="scope-label">WORKFLOW MẪU · CHƯA SINH HARNESS</span><button class="button small ghost" style="margin-left:auto" data-action="workflow-language">✧ Chỉnh bằng lời</button></div>${state.workflow.map((w,i)=>`<div class="workflow-row" data-wf-row="${esc(w.id)}"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div class="workflow-node ${w.type==='gate'?'gate-node':''}" draggable="true" data-wf="${esc(w.id)}"><span class="wf-icon">${w.type==='gate'?'◇':w.type==='report'?'▤':'♙'}</span><div><b>${esc(w.name)}</b><small>${esc(w.role)}</small></div></div><div class="flow-actions"><button class="icon-btn" data-wf-move="${esc(w.id)}" data-dir="-1" ${i===0?'disabled':''} aria-label="Đưa bước ${esc(w.name)} lên">↑</button><button class="icon-btn" data-wf-move="${esc(w.id)}" data-dir="1" ${i===state.workflow.length-1?'disabled':''} aria-label="Đưa bước ${esc(w.name)} xuống">↓</button></div></div>`).join('')}<button class="button small" data-action="add-step">＋ Thêm bước</button></div><p class="sample-note">Canvas trong bản mẫu dùng danh sách kéo thả để anh xem thứ tự, role, báo cáo và gate. Chưa biên dịch hay áp dụng harness vào project.</p>`}
function reportEntries(){return [{id:'brief',title:'Đề xuất sản phẩm & mục tiêu',who:'Product / BA · G1',state:'done',text:'Bối cảnh đã chốt trong kịch bản mẫu'},{id:'plan',title:'Kế hoạch chia task & tổ chức đội',who:'PM + Tech Lead · G2',state:state.approved?'done':'waiting',text:state.approved?'Đã duyệt trong bản mẫu':'Cần anh xem và quyết định'},{id:'acceptance',title:'Kết quả tích hợp & nghiệm thu',who:'Tester + Product · G3',state:countDone()===state.tasks.length?'waiting':'idle',text:countDone()===state.tasks.length?'Kết quả mô phỏng đã sẵn sàng':'Chưa có bằng chứng — chờ các task hoàn thành'}]}
function renderReports(){return pageHead('LINGO / HỒ SƠ CÔNG VIỆC','Báo cáo để anh quyết định','Tóm tắt dễ đọc trước, bằng chứng và chi tiết mở thêm khi cần.')+`<div class="card">${reportEntries().map(r=>`<button class="report-row" data-report="${r.id}"><span class="report-icon">▤</span><span><b>${r.title}</b><small>${r.who} · ${r.text}</small></span>${badge(r.state)}</button>`).join('')}</div><div class="section-title"><h2>Quyết định đã ghi nhận</h2></div><div class="card timeline">${decisionTimeline()}</div><p class="sample-note">Mọi báo cáo và kết quả trong trang này đều là dữ liệu minh họa hoặc thao tác mô phỏng, chưa có kiểm thử hay phát hành thực tế.</p>`}
function renderGates(){const g=pendingGate();return pageHead('VIỆC CỦA ANH','Quyết định đúng lúc.','PM gom bối cảnh, phương án và kết quả để anh không phải theo từng cuộc chat.')+(g?`<article class="card gate-detail"><div class="space-between"><span class="eyebrow">LINGO / ${esc(title())}</span>${badge('waiting','Chờ Owner')}</div><h2>${g==='G2'?'Các đội có thể bắt đầu theo kế hoạch này không?':'Kết quả này đạt chưa và có được phát hành?'}</h2><p>${g==='G2'?state.tasks.length+' task được chia thành 3 đội. Chốt phụ thuộc và quyền thực hiện trước khi giao việc.':'Các task đã hoàn thành trong mô phỏng. Nghiệm thu và cho phép phát hành là hai quyết định riêng.'}</p><button class="button" data-action="${g==='G2'?'review-plan':'review-release'}">▤ Đọc báo cáo và quyết định ↗</button><div class="decision-options"><div class="note-box">${g==='G2'?'Chưa duyệt → chưa bắt đầu triển khai. Duyệt kế hoạch không tự cấp quyền production.':'Chưa cho phép phát hành → dừng trước production. Phiên bản thay đổi phải được đánh giá lại.'}</div></div></article>`:`<div class="card empty-state">${av('pm','done','xl')}<h3>Chưa có quyết định nào đang chờ.</h3><p>${state.releaseApproved&&!state.released?'Anh đã cho phép phát hành trong bản mẫu; có thể mô phỏng phát hành ở công việc.':'Anh có thể xem đội đang thực hiện hoặc lịch sử các quyết định.'}</p><button class="button" data-screen="project">Về công việc →</button></div>`)+`<div class="section-title"><h2>Lịch sử quyết định</h2></div><div class="card timeline">${decisionTimeline()}</div>`}
function renderOverview(){return pageHead('CÔNG TY CỦA HOÀNG','Chào anh, đội ngũ đã có mặt.','Bắt đầu từ những việc cần anh quyết định, rồi nhìn vào các đội đang phối hợp.',`<button class="button small" data-screen="secretary">✧ Gặp Thư ký</button>`)+gateBanner()+`<div class="overview-grid"><button class="card project-card" data-screen="project"><span class="project-icon">L</span><h3>Lingo</h3><p>Nhắc người dùng học mỗi ngày</p><div class="space-between"><span class="small muted">${state.tasks.length} task · 3 đội</span>${badge(pendingGate()?'waiting':'working',pendingGate()?'Chờ anh':'Đang mô phỏng')}</div><div class="progress-line"><i style="width:${countDone()/state.tasks.length*100}%"></i></div></button><button class="card project-card" data-action="joy-info"><span class="project-icon purple">J</span><h3>Joy</h3><p>Project tham chiếu cho workflow và harness.</p><span class="scope-label">Chưa kết nối dữ liệu thật</span></button></div><div class="section-title"><h2>Đội điều phối công việc</h2><button class="button small ghost" data-screen="teams">Xem các đội →</button></div>`+officeHero()}
function renderSecretary(){return pageHead('THƯ KÝ AI OFFICE','Anh đưa mục tiêu. Mình cùng sắp xếp.','Tiếp nhận đề bài, chọn đội phù hợp và giữ việc trao đổi gọn trong một nơi.')+`<div class="office-hero"><div class="office-intro"><div class="person-line">${av('secretary','working','lg')}<div><b>Nhi · Thư ký</b><small>Hỗ trợ toàn công ty</small></div></div><h2>Hôm nay anh muốn<br>đội ngũ làm điều gì?</h2><p>Mở chat bên phải hoặc bắt đầu bằng một việc dưới đây.</p></div><div class="office-scene">${desk('secretary','working')}</div></div><div class="section-title"><h2>Bắt đầu một cuộc trao đổi</h2></div><div class="split-2"><button class="card info-card" style="text-align:left" data-action="new-work"><h3>＋ Giao một đề bài chung</h3><p>Ghi mục tiêu; PM và Product làm rõ trước khi đề xuất task.</p></button><button class="card info-card" style="text-align:left" data-screen="workflows"><h3>⌘ Chỉnh cách đội làm việc</h3><p>Role, workflow, báo cáo và gate có thể nhìn lại và sửa.</p></button></div><div class="section-title"><h2>Điều anh nên thấy trước</h2></div><div class="note-box">Mục tiêu → đề xuất chia việc → quyết định của anh → kết quả có bằng chứng. Không phải đọc hết terminal để biết đội đang làm gì.</div>`}
function renderNewBrief(){return pageHead('LINGO / ĐỀ BÀI MỚI',esc(state.customWork.title),'Đã ghi đề bài trong bản mẫu. Chưa tự suy ra task hoặc khởi tạo đội.')+`<div class="card info-card"><h3>Đề bài của anh</h3><p style="white-space:pre-wrap">${esc(state.customWork.description)}</p><div class="note-box"><b>Bước tiếp theo:</b> PM và Product hỏi rõ mục tiêu, người dùng, phạm vi và bằng chứng. Bản mẫu này chưa có AI thật để tự phân tích đề bài bất kỳ.</div><div class="simulate-bar"><button class="button primary" data-action="show-example">Xem ví dụ phân rã “Nhắc học”</button><button class="button" data-action="chat-open">Trao đổi với PM</button></div></div>`}
function openModal(heading,body,footer='',wide=false){previousFocus=document.activeElement;const layer=document.querySelector('#modal-layer');layer.hidden=false;const modal=document.querySelector('#modal');modal.className=wide?'wide':'';modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${heading}</h2><button class="icon-btn" data-action="close-modal" aria-label="Đóng">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;document.body.style.overflow='hidden';modal.focus()}
function closeModal(){document.querySelector('#modal-layer').hidden=true;document.body.style.overflow='';previousFocus?.isConnected&&previousFocus.focus()}
function taskModal(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;openModal(esc(t.title),`<div class="task-detail-top"><span class="scope-label">TASK ${esc(t.id)} · ${teams[t.team].short}</span>${badge(t.status)}</div><p>${esc(t.description)}</p><h3>Kết quả phải bàn giao</h3><ul class="checklist">${t.criteria.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><div class="form-row"><div><h3>Chịu trách nhiệm</h3><div class="person-line">${av(t.owner)}<div><b>${esc(state.roles[t.owner].name)} · ${esc(state.roles[t.owner].title)}</b><small>${teams[t.team].title}</small></div></div></div><div><h3>Điều kiện được bắt đầu</h3><p>${t.deps.length?'Các task '+esc(t.deps.join(', '))+' hoàn thành và đã chốt G2.':'Đã chốt G2 và có đủ context đầu vào.'}</p></div></div><h3>Luồng thực hiện của task</h3><div class="note-box">Nhận đầu vào → thực hiện theo chuyên môn → kiểm chứng độc lập → bàn giao. ${t.owner==='dev'?'Developer viết test, Tester kiểm tra, Reviewer đánh giá thay đổi.':''}</div><h3>Context đi cùng</h3><p>Mục tiêu công việc cha, quyết định G1/G2, quy tắc project và kết quả từ task phụ thuộc. Session không tự nhận toàn bộ hội thoại của các đội khác.</p><p class="inline-note">Mọi trạng thái và bằng chứng tại đây là minh họa. Chưa có file/code/test thực tế.</p>`,`<button class="button" data-team-open="${t.team}">Vào đội phụ trách</button><button class="button primary" data-action="task-to-chat" data-id="${esc(t.id)}">Hỏi PM về task này</button>`)}
function teamModal(id){const t=teams[id];const tasks=state.tasks.filter(x=>x.team===id);openModal(t.title,`<div class="space-between"><span class="eyebrow">${id==='coord'?'WORKSPACE CHA':'WORKSPACE CON'}</span>${badge(state.teamsStarted?'working':'draft',state.teamsStarted?'Đội mô phỏng':'Chưa bắt đầu')}</div><p>${t.purpose}</p><div class="team-floor" style="border-radius:10px">${t.roles.map(r=>desk(r,state.teamsStarted?'working':'idle',id)).join('')}</div><h3>Phần việc được giao</h3>${tasks.map(x=>`<button class="report-row" data-task="${esc(x.id)}"><span class="task-id">${esc(x.id)}</span><span><b>${esc(x.title)}</b><small>${x.deps.length?'Chờ '+esc(x.deps.join(', ')):'Không có phụ thuộc'}</small></span>${badge(x.status)}</button>`).join('')}<h3>PM của đội phối hợp thế nào?</h3><p>${id==='coord'?'PM tổng giữ mục tiêu, giao các phần việc cho đội con, xử lý phụ thuộc và tổng hợp báo cáo cho anh.':'PM đội con điều phối phần được giao và báo kết quả về PM tổng. Anh vẫn trao đổi chính với PM tổng, không phải nối context giữa các đội.'}</p><p class="inline-note">Role mẫu có thể giống nhau giữa các đội; mỗi nhân sự của mỗi đội có định danh/session riêng. Chưa tạo session thật.</p>`,`<button class="button primary" data-action="close-modal">Đã hiểu</button>`)}
function personModal(role,team){const p=(state.assignmentRoles||state.roles)[role]||state.roles[role];openModal(`${esc(p.name)} · ${esc(p.title)}`,`<div class="person-line">${av(role,'working','xl')}<div><b>${esc(teams[team].title)}</b><small>${esc(p.provider)} · cấu hình mặc định · ${esc(p.effort)}</small></div></div><h3>Trách nhiệm</h3><p>${esc(p.description)}</p><h3>Quy tắc đang dùng trong bản mẫu</h3><div class="note-box">${esc(p.rule)}</div><h3>Context và định danh</h3><div class="context-tree">Project: <b>Lingo</b><br>Workspace: <b>${esc(teams[team].short)}</b><br>Nhân sự: <b>${esc(team+'/'+role)}</b><br>Session: <b>${state.teamsStarted?'session-mẫu-'+esc(team+'-'+role):'chưa khởi tạo'}</b></div><p class="inline-note">Cấu hình riêng của project bổ sung vào role mẫu. Đổi provider trong bản thật cần xử lý bàn giao và trạng thái worker cũ; mockup chỉ minh họa lựa chọn.</p>`,`<button class="button" data-role-edit="${esc(role)}">Xem cấu hình role mẫu</button><button class="button primary" data-action="close-modal">Đóng</button>`)}
function roleEdit(id){const p=state.roles[id];openModal(`Cấu hình role · ${esc(p.title)}`,`<form id="role-form" data-role-id="${esc(id)}"><div class="person-line" style="margin-bottom:17px">${av(id,'working','lg')}<div><b>${esc(p.title)}</b><small>Thư viện dùng chung · bản mẫu</small></div></div><div class="form-row"><label class="field">Agent / provider<select name="provider"><option ${p.provider==='Claude'?'selected':''}>Claude</option><option ${p.provider==='Codex'?'selected':''}>Codex</option></select></label><label class="field">Mức suy luận (minh họa)<select name="effort">${['Low','Medium','High'].map(e=>`<option ${p.effort===e?'selected':''}>${e}</option>`).join('')}</select></label></div><label class="field">Model<input name="model" value="${esc(p.model||'Mặc định của provider')}" placeholder="Tên model"><small>Giá trị minh họa; chưa kiểm tra tổ hợp model/effort với môi trường chạy.</small></label><label class="field">Trách nhiệm<textarea name="description">${esc(p.description)}</textarea></label><label class="field">Quy tắc làm việc — viết bằng lời của anh<textarea name="rule">${esc(p.rule)}</textarea><small>Ví dụ: “Trước khi sửa bug phải viết test fail; sửa xong chạy test pass.”</small></label><div class="note-box">Thay đổi này lưu ở role mẫu trong mockup. Không tự áp dụng vào nhân sự/phiên chạy đang hoạt động; chưa sinh hoặc sửa harness.</div></form>`,`<button class="button" data-action="close-modal">Hủy</button><button class="button primary" type="submit" form="role-form">Xem thay đổi trước khi lưu</button>`)}
function planModal(){openModal('G2 · Chốt kế hoạch chia việc',`<span class="status waiting">Báo cáo minh họa · cần anh quyết định</span><h3>Mục tiêu</h3><p>Nhắc đúng người, đúng lịch đã chọn, bỏ qua khi đã học và không gửi trùng. Kênh trong ví dụ: thông báo trong ứng dụng.</p><h3>Đề xuất phân rã</h3>${state.tasks.map(t=>`<div class="report-row"><span class="task-id">${esc(t.id)}</span><span><b>${esc(t.title)}</b><small>${teams[t.team].short} · ${t.deps.length?'chờ '+esc(t.deps.join(', ')):'bắt đầu trước'}</small></span></div>`).join('')}<h3>Vì sao tổ chức như vậy?</h3><p>Chốt hợp đồng chung ở A. B và C triển khai song song sau A. C và D ở cùng đội để giữ context; E kiểm tra kết quả tổng, không chỉ cộng trạng thái task.</p><h3>Quyền thực hiện khi duyệt bản mẫu này</h3><ul><li>Cho phép giao việc và mô phỏng các task theo kế hoạch.</li><li>Quy tắc đề xuất: Developer viết test trước khi sửa; có Tester và Reviewer độc lập.</li><li>Không cấp quyền push hoặc phát hành thật. G3 quyết định nghiệm thu/phát hành riêng.</li></ul><div class="note-box">Bản mô phỏng gom tiến độ thực hiện, kiểm thử và review thành từng lượt. Bản thật phải lưu bằng chứng từng bước; không xem việc agent chạy xong là kiểm thử đã đạt.</div>`,`<button class="button" data-action="request-change">Yêu cầu chỉnh kế hoạch</button><button class="button primary" data-action="approve-plan">Duyệt kế hoạch mẫu & lập đội →</button>`,true)}
function approvePlan(){if(state.tasks.some(t=>t.deps.some(d=>!state.tasks.some(x=>x.id===d))))return toast('Có phụ thuộc chưa tồn tại.');state.approved=true;if(!state.teamsStarted)state.assignmentRoles=structuredClone(state.roles);state.teamsStarted=true;state.revision++;updateReadiness();state.decisions.push({title:'G2 · Duyệt kế hoạch mẫu',text:`Chấp nhận ${state.tasks.length} task và 3 đội. Chỉ cho phép mô phỏng; chưa có quyền phát hành thật.`});state.messages.pm.push({from:'agent',text:'Anh đã chốt G2 trong bản mẫu. Task đủ điều kiện được mở trước; các task phụ thuộc vẫn chờ.\n\nAnh có thể bấm “Mô phỏng một lượt thực hiện” để xem các đội phối hợp.'});persist();closeModal();screen='project';projectTab='tasks';render();toast('Đã duyệt G2 trong bản mẫu. Chưa tạo đội hoặc chạy agent thật.')}
function updateReadiness(){for(const t of state.tasks){if(['working','done'].includes(t.status))continue;t.status=state.approved?(t.deps.every(d=>state.tasks.find(x=>x.id===d)?.status==='done')?'ready':'blocked'):'draft'}}
function simulate(){if(!state.approved)return toast('Cần chốt G2 trước.');if(state.releaseApproved){state.released=true;state.decisions.push({title:'Phát hành — mô phỏng',text:'Đã mô phỏng triển khai phiên bản được duyệt ở G3. Không có lệnh deploy thực tế.'});persist();render();return toast('Đã mô phỏng phát hành, không triển khai thật.')}const working=state.tasks.filter(t=>t.status==='working');if(working.length){working.forEach(t=>t.status='done');state.messages.pm.push({from:'agent',text:`Task ${working.map(t=>t.id).join(', ')} đã hoàn thành trong lượt mô phỏng, bao gồm bàn giao và kiểm tra mẫu.\n\n${working.some(t=>t.id==='A')?'B và C đủ điều kiện chạy song song sau khi A hoàn tất.':'Em sẽ mở các task có đủ phụ thuộc.'}`})}else{const ready=state.tasks.filter(t=>t.status==='ready');if(!ready.length)return toast('Đã hoàn thành các task. Mời anh xem báo cáo nghiệm thu G3.');ready.forEach(t=>t.status='working');state.messages.pm.push({from:'agent',text:`Đang mô phỏng thực hiện task ${ready.map(t=>t.id).join(', ')}${ready.length>1?' song song':''}. Đây là trạng thái minh họa, chưa có agent thật.`})}state.simulationRound++;updateReadiness();if(state.tasks.every(t=>t.status==='done'))state.messages.pm.push({from:'agent',text:'Các task của ví dụ đã hoàn thành trong mô phỏng. Em đưa kết quả tổng tới G3 để anh nghiệm thu.\n\nChưa có test hay bằng chứng thật; báo cáo G3 là mẫu trình bày cách anh ra quyết định.'});persist();render()}
function releaseModal(){if(countDone()!==state.tasks.length){openModal('Báo cáo nghiệm thu chưa sẵn sàng',`<p>Chưa đủ đầu ra của các task để nghiệm thu bản tích hợp.</p><div class="note-box">Đây là trạng thái “chưa có bằng chứng”, không phải một báo cáo PASS. Anh có thể duyệt kế hoạch và mô phỏng các lượt thực hiện để xem G3.</div>`,`<button class="button primary" data-action="close-modal">Đã hiểu</button>`);return}openModal('G3 · Nghiệm thu kết quả & quyền phát hành',`<span class="status waiting">Báo cáo mẫu · phiên bản demo-r1</span><h3>Kết quả sản phẩm trong ví dụ</h3><ul><li>Người dùng chọn lịch, bật/tắt nhắc theo múi giờ.</li><li>Hệ thống xác định điều kiện nhận nhắc và kiểm soát gửi trùng.</li><li>Có kết quả gửi, thử lại và hành trình nghiệm thu tổng.</li></ul><h3>Bằng chứng</h3><div class="note-box"><b>Chỉ có dữ liệu mô phỏng.</b> Bản thật cần demo, test report, review và kết quả tích hợp gắn với đúng phiên bản. Mockup này chưa tạo các bằng chứng đó.</div><h3>Ngoài phạm vi</h3><p>Email, SMS, cá nhân hóa nội dung. Chưa đủ dữ liệu để kết luận tăng tỷ lệ quay lại sau phát hành.</p><h3>Anh quyết định</h3><div class="decision-options"><button class="decision-option recommended" data-action="accept-release"><b>Chấp nhận & cho phép mô phỏng phát hành</b><small>Lưu riêng quyết định nghiệm thu và quyền phát hành demo-r1.</small></button><button class="decision-option" data-action="accept-only"><b>Chấp nhận nhưng chưa phát hành</b><small>Giữ dừng ở trước bước phát hành.</small></button><button class="decision-option" data-action="release-change"><b>Yêu cầu sửa trước khi nghiệm thu</b><small>Ghi rõ phần chưa đạt để PM trả về đội phụ trách.</small></button></div>`,`<button class="button" data-action="close-modal">Xem sau</button>`)}
function acceptRelease(allow){state.releaseApproved=allow;state.decisions.push({title:'G3 · Nghiệm thu bản mẫu',text:allow?'Chấp nhận kết quả minh họa và cho phép mô phỏng phát hành demo-r1.':'Chấp nhận kết quả minh họa, chưa cho phép phát hành.'});persist();closeModal();render();toast(allow?'Đã cho phép mô phỏng phát hành.':'Đã ghi nhận nghiệm thu; chưa cấp quyền phát hành.')}
function showReport(id){if(id==='plan')return planModal();if(id==='acceptance')return releaseModal();openModal('G1 · Đề xuất sản phẩm trong ví dụ',`<span class="status done">Bối cảnh mẫu đã chốt</span><h3>Vấn đề</h3><p>Người dùng có thể quên quay lại học. Giả định của ví dụ là một lịch nhắc do người dùng chọn sẽ hỗ trợ thói quen.</p><h3>Phạm vi được chọn</h3><p>Thông báo trong ứng dụng theo giờ và múi giờ người dùng; không nhắc khi đã học trong ngày hoặc tắt nhận nhắc.</p><h3>Điều chưa được chứng minh</h3><p>Chưa có dữ liệu người dùng thật để khẳng định giải pháp tăng retention. Sau phát hành cần đo kết quả theo mục tiêu được Owner thống nhất.</p><div class="note-box">Đây là dữ liệu dựng sẵn để minh họa G2 và cách phân rã task; không phải quyết định thật trước đây của anh.</div>`,`<button class="button primary" data-action="close-modal">Đóng</button>`)}
function renderChat(){const key=screen==='secretary'?'secretary':'pm';const p=state.roles[key];document.querySelector('#chat-avatar').innerHTML=avatarSvg(p.avatar,'working');document.querySelector('#chat-name').textContent=p.name+' · '+(key==='pm'?'PM':'Thư ký');document.querySelector('#chat-role').textContent=key==='pm'?'Đầu mối chính của công việc':'Hỗ trợ toàn công ty';document.querySelector('#chat-context').textContent=key==='pm'?'Lingo / '+title():'AI Office / điều phối chung';document.querySelector('#chat-messages').innerHTML=state.messages[key].map(m=>`<div class="message ${m.from==='me'?'me':''}"><div class="meta"><b>${m.from==='me'?'Anh':esc(p.name)}</b><span>· bản mẫu</span></div><div class="bubble-text">${esc(m.text)}</div>${m.doc?'<button class="chat-doc" data-action="review-plan">▤ Kế hoạch chia task & đội ngũ<span>Xem báo cáo để quyết định tại G2 ↗</span></button>':''}</div>`).join('');const log=document.querySelector('#chat-messages');log.scrollTop=log.scrollHeight}
function sendChat(text){text=text.trim();if(!text)return;const key=screen==='secretary'?'secretary':'pm';state.messages[key].push({from:'me',text});let answer;if(/song song/i.test(text))answer='Trong ví dụ: A chốt hợp đồng dữ liệu trước. B và C có thể chạy song song sau A. D chờ C. E chờ B, C và D.\n\nCùng lúc chạy nhiều agent chỉ phù hợp khi phạm vi ghi và tài nguyên không xung đột.';else if(/chia|tách|task/i.test(text))answer='Em chia theo kết quả có thể bàn giao: A thống nhất hợp đồng; B là trải nghiệm thiết lập; C–D là phần gửi nhắc; E kiểm tra hành trình tổng.\n\nKhông tạo một đội cho mỗi task. C và D cùng đội; đội điều phối giữ A và E.';else if(/test|kiểm thử|fail/i.test(text))answer='Quy tắc mẫu: Developer viết test chứng minh hành vi chưa đạt rồi mới sửa; sau sửa test phải đạt. Tester kiểm chứng độc lập và Reviewer xem thay đổi.\n\nAnh có thể mở Nhân sự & role → Developer để chỉnh quy tắc bằng lời.';else if(/gate|duyệt|quyết định/i.test(text))answer='G1 chốt sản phẩm. G2 chốt kế hoạch và quyền tự chạy. G3 nghiệm thu và quyết định phát hành. Đổi mục tiêu/phạm vi/chi phí vượt quyền thì PM hỏi lại anh.\n\nChưa trả lời không có nghĩa là đồng ý.';else if(/model|codex|claude|role/i.test(text))answer='Mở Nhân sự & role để xem provider, mức suy luận và quy tắc mẫu. Trong hệ thống thật, đổi provider cần bàn giao context và xử lý session cũ; mockup chỉ lưu lựa chọn minh họa.';else if(key==='secretary')answer='Em đã ghi đề bài trong cuộc trao đổi của bản mẫu. Anh có thể dùng “Giao việc mới” để ghi mục tiêu, hoặc mở Workflow / Nhân sự để chỉnh cấu hình.\n\nChưa có AI thật để phân tích yêu cầu này hay chuyển lời sang các session.';else answer='Em đã ghi ý kiến của anh trong bản mẫu. Phản hồi ở đây dùng kịch bản có sẵn, chưa có AI thật phân tích nội dung này.\n\nAnh có thể mở task, yêu cầu chỉnh kế hoạch hoặc thêm task đề xuất để thử cách trao đổi và quyết định.';state.messages[key].push({from:'agent',text:answer});persist();renderChat();document.querySelector('#chat-input').value=''}
function simpleForm(titleText,id,fields,submit='Lưu bản mẫu'){openModal(titleText,`<form id="${id}">${fields}</form>`,`<button class="button" data-action="close-modal">Hủy</button><button class="button primary" type="submit" form="${id}">${submit}</button>`)}
function addTask(){simpleForm('Thêm task đề xuất','add-task-form',`<label class="field">Kết quả task cần bàn giao<input required name="title" placeholder="Ví dụ: Kiểm tra người dùng đổi múi giờ"></label><label class="field">Đội phụ trách<select name="team">${Object.entries(teams).map(([id,t])=>`<option value="${id}">${t.title}</option>`).join('')}</select></label><label class="field">Phụ thuộc<select name="dependency"><option value="">Không phụ thuộc</option>${state.tasks.map(t=>`<option value="${esc(t.id)}">${esc(t.id+' · '+t.title)}</option>`).join('')}</select></label><label class="field">Tiêu chí chấp nhận<textarea required name="criteria" placeholder="Điều gì cần đúng để task được coi là hoàn thành?"></textarea></label><div class="note-box">Task bổ sung được đưa vào đề xuất. Nếu kế hoạch đã duyệt, cần chốt lại G2 trước khi giao thêm phạm vi.</div>`,'Thêm vào đề xuất')}
function newWork(){simpleForm('Giao một đề bài chung','new-work-form',`<label class="field">Mục tiêu / tên công việc<input name="title" required placeholder="Tôi muốn người dùng…"></label><label class="field">Anh muốn giải quyết vấn đề gì?<textarea name="description" required placeholder="Ai gặp vấn đề, hiện nay họ làm gì, kết quả anh mong muốn…"></textarea></label><div class="note-box">Lưu đề bài trong bản mẫu; chưa dùng AI thật để tự chia task. Đội cần làm rõ trước khi lập kế hoạch.</div>`,'Ghi đề bài mẫu')}
function workflowMove(id,offset){const i=state.workflow.findIndex(w=>w.id===id),j=i+offset;if(j<0||j>=state.workflow.length)return;[state.workflow[i],state.workflow[j]]=[state.workflow[j],state.workflow[i]];state.workflowDirty=true;render()}
function validateWorkflow(){const ids=state.workflow.map(w=>w.id);if(ids.indexOf('wf4')>ids.indexOf('wf5'))return 'G2 phải trước triển khai. Hãy đưa bước chốt kế hoạch lên trước.';if(ids.indexOf('wf8')>ids.indexOf('wf9'))return 'G3 phải trước phát hành. Hãy giữ gate phát hành trước bước triển khai production.';if(ids.indexOf('wf6')<ids.indexOf('wf5'))return 'Kiểm thử & review kết quả phải sau bước triển khai trong luồng mẫu này.';return null}
const actions={
 'close-modal':closeModal,'review-plan':planModal,'review-release':releaseModal,'approve-plan':approvePlan,'simulate':simulate,'accept-release':()=>acceptRelease(true),'accept-only':()=>acceptRelease(false),'add-task':addTask,'new-work':newWork,
 'chat-toggle':()=>{chatClosed=!chatClosed;render()},'chat-open':()=>{closeModal();chatClosed=false;render();document.querySelector('#chat-input').focus()},
 'menu':()=>document.querySelector('.sidebar').classList.toggle('mobile-open'),
 'theme':()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('aio-prototype-theme',theme)}catch{}},
 'reset':()=>openModal('Đặt lại bản mẫu?',`<p>Xóa các lựa chọn, task thêm và tin nhắn trong mockup này để quay về kịch bản ban đầu.</p><p class="inline-note">Không ảnh hưởng app thật, Obsidian note hoặc project Joy.</p>`,`<button class="button" data-action="close-modal">Giữ lại</button><button class="button danger" data-action="confirm-reset">Đặt lại</button>`),
 'confirm-reset':()=>{state=initial();screen='project';projectTab='tasks';taskView='list';persist();closeModal();render();toast('Đã đặt lại kịch bản mẫu.')},
 'show-example':()=>{state.customWork=null;persist();render()},
 'edit-brief':()=>simpleForm('Góp ý đề bài và phạm vi','brief-comment-form',`<label class="field">Điều anh muốn làm rõ / thay đổi<textarea required name="comment" placeholder="Ví dụ: cần xem cách nhắc theo múi giờ…"></textarea></label><div class="note-box">Ý kiến được gửi vào chat PM và hồ sơ quyết định của bản mẫu. Chưa tự phân tích lại kế hoạch bằng AI.</div>`,'Gửi ý kiến cho PM'),
 'request-change':()=>simpleForm('Yêu cầu chỉnh kế hoạch','plan-change-form',`<label class="field">Phần nào cần thay đổi?<textarea required name="comment" placeholder="Ví dụ: muốn xem trải nghiệm trước, hoặc chưa làm phần thử lại…"></textarea></label><div class="note-box">Ghi phản hồi, giữ G2 chờ quyết định. PM thật sẽ phân tích và đưa lại kế hoạch; mockup chưa tự sửa ý nghĩa các task.</div>`,'Ghi phản hồi'),
 'release-change':()=>simpleForm('Yêu cầu sửa trước khi nghiệm thu','release-change-form',`<label class="field">Điều chưa đạt<textarea required name="comment"></textarea></label><label class="field">Task cần kiểm tra lại<select name="task">${state.tasks.map(t=>`<option value="${esc(t.id)}">${esc(t.id+' · '+t.title)}</option>`).join('')}</select></label>`,'Trả task để sửa'),
 'task-to-chat':n=>{const t=state.tasks.find(x=>x.id===n.dataset.id);closeModal();chatClosed=false;render();document.querySelector('#chat-input').value='Làm rõ task '+t.id+': '+t.title;document.querySelector('#chat-input').focus()},
 'joy-info':()=>openModal('Joy · project tham chiếu',`<div class="person-line"><span class="project-icon purple">J</span><div><b>Harness và workflow hiện tại giữ nguyên</b><small>Chưa kết nối runtime vào mockup này</small></div></div><p>Ví dụ phân rã trong mockup đang thuộc project Lingo. Joy chỉ là mục tham chiếu để cho thấy app có thể tổ chức nhiều project.</p><div class="context-tree">AI Office: <b>role & workflow dùng chung</b><br>Joy: <b>nghiệp vụ, skill, kiến trúc và công cụ riêng</b><br>Workspace: <b>đề bài, kế hoạch, quyết định và bằng chứng</b></div>`,`<button class="button primary" data-action="close-modal">Đã hiểu</button>`),
 'project-info':()=>openModal('Thêm project vào AI Office',`<p>Trong bản thật, anh có thể liên kết project Orca có sẵn hoặc tạo project mới, rồi bổ sung hồ sơ và cách làm riêng.</p><div class="note-box">Bản mẫu này có một project Lingo để thử hành trình đầy đủ. Chưa tạo repo, workspace hay đọc dữ liệu Orca thật.</div>`,`<button class="button primary" data-action="close-modal">Đóng</button>`),
 'add-role':()=>simpleForm('Thêm role mẫu','add-role-form',`<label class="field">Tên role<input required name="title" placeholder="Ví dụ: Security Engineer"></label><label class="field">Chịu trách nhiệm gì?<textarea required name="description"></textarea></label><label class="field">Quy tắc làm việc<textarea required name="rule"></textarea></label>`,'Tạo role mẫu'),
 'add-step':()=>simpleForm('Thêm bước vào workflow','add-step-form',`<label class="field">Tên bước<input required name="name" placeholder="Ví dụ: Đánh giá bảo mật"></label><div class="form-row"><label class="field">Loại bước<select name="type"><option value="work">Giao việc cho role</option><option value="report">Tạo báo cáo</option><option value="gate">Gate chờ quyết định</option></select></label><label class="field">Người phụ trách<input required name="role" placeholder="Security / Owner…"></label></div><div class="note-box">Bước mới được thêm trước gate phát hành. Anh có thể kéo đổi thứ tự rồi lưu phiên bản mẫu.</div>`,'Thêm bước'),
 'workflow-language':()=>simpleForm('Chỉnh workflow bằng lời','workflow-language-form',`<label class="field">Anh muốn đội làm khác đi thế nào?<textarea required name="request" placeholder="Ví dụ: Thêm báo cáo kiểm thử trước khi tôi nghiệm thu"></textarea></label><div class="note-box">Bản mẫu hỗ trợ kịch bản “thêm báo cáo” hoặc “thêm gate”. Yêu cầu khác sẽ được ghi lại, chưa có AI thật biên dịch harness.</div>`,'Xem đề xuất thay đổi'),
 'save-workflow':()=>{const error=validateWorkflow();if(error)return toast(error);if(!state.workflowDirty)return toast('Chưa có thay đổi mới để lưu.');state.workflowVersion++;state.workflowDirty=false;persist();render();toast('Đã lưu workflow mẫu v'+state.workflowVersion+'. Chưa áp dụng vào lần chạy hiện tại.')}
};
document.addEventListener('click',e=>{const n=e.target.closest('[data-action],[data-screen],[data-tab],[data-taskview],[data-task],[data-team-open],[data-role],[data-role-edit],[data-report],[data-wf-move],[data-prompt]');if(!n)return;if(n.dataset.action){actions[n.dataset.action]?.(n);return}if(n.dataset.screen){closeModal();setScreen(n.dataset.screen);return}if(n.dataset.tab){projectTab=n.dataset.tab;render();return}if(n.dataset.taskview){taskView=n.dataset.taskview;render();return}if(n.dataset.task){taskModal(n.dataset.task);return}if(n.dataset.teamOpen){teamModal(n.dataset.teamOpen);return}if(n.dataset.role){personModal(n.dataset.role,n.dataset.team||'coord');return}if(n.dataset.roleEdit){roleEdit(n.dataset.roleEdit);return}if(n.dataset.report){showReport(n.dataset.report);return}if(n.dataset.wfMove){workflowMove(n.dataset.wfMove,Number(n.dataset.dir));return}if(n.dataset.prompt){chatClosed=false;render();sendChat(n.dataset.prompt)}});
document.addEventListener('submit',e=>{const form=e.target;e.preventDefault();const fd=new FormData(form);if(form.id==='chat-form'){sendChat(document.querySelector('#chat-input').value);return}if(form.id==='role-form'){const id=form.dataset.roleId;const before=state.roles[id];const next={...before,provider:fd.get('provider'),effort:fd.get('effort'),model:String(fd.get('model')).trim(),description:String(fd.get('description')).trim(),rule:String(fd.get('rule')).trim()};openModal('Xác nhận thay đổi role mẫu',`<div class="scope-label">CHỈ LƯU THƯ VIỆN BẢN MẪU</div><h3>${esc(before.title)}</h3><div class="rule-diff"><div>Trước: ${esc(before.provider)} · ${esc(before.effort)}<br>${esc(before.rule)}</div><div>Sau: ${esc(next.provider)} · ${esc(next.effort)}<br>${esc(next.rule)}</div></div><p class="inline-note">Không đổi session thực tế hoặc harness của project. Lần chạy đang hoạt động sẽ cần thao tác nâng phiên bản riêng.</p>`,`<button class="button" data-role-edit="${esc(id)}">Quay lại chỉnh</button><button class="button primary" id="confirm-role-save">Lưu role mẫu</button>`);document.querySelector('#confirm-role-save').onclick=()=>{state.roles[id]=next;persist();closeModal();render();toast('Đã lưu cấu hình role trong bản mẫu.')};return}if(form.id==='add-task-form'){const id=String.fromCharCode(65+state.tasks.length);state.tasks.push({id,title:String(fd.get('title')).trim(),description:'Task do anh bổ sung trong bản mẫu.',team:fd.get('team'),deps:fd.get('dependency')?[fd.get('dependency')]:[],owner:'dev',status:'draft',criteria:String(fd.get('criteria')).trim().split('\n').filter(Boolean)});state.approved=false;state.releaseApproved=false;state.released=false;updateReadiness();state.decisions.push({title:'Đề xuất bổ sung task '+id,text:'Thêm phạm vi; cần chốt lại G2 trước khi thực hiện.'});persist();closeModal();screen='project';projectTab='tasks';taskView='list';render();toast('Đã thêm task đề xuất; G2 cần được chốt lại.');return}if(form.id==='new-work-form'){state.customWork={title:String(fd.get('title')).trim(),description:String(fd.get('description')).trim()};persist();closeModal();setScreen('project');return}if(['brief-comment-form','plan-change-form'].includes(form.id)){const text=String(fd.get('comment')).trim();state.messages.pm.push({from:'me',text},{from:'agent',text:'Em đã ghi ý kiến trong bản mẫu. Cần phân tích và xác nhận kế hoạch mới trước khi áp dụng; mockup chưa có AI để tự sửa các task.'});state.decisions.push({title:'Owner góp ý · chờ xử lý',text});if(form.id==='plan-change-form'){state.approved=false;updateReadiness()}persist();closeModal();chatClosed=false;render();return}if(form.id==='release-change-form'){const id=fd.get('task'),t=state.tasks.find(x=>x.id===id);const affected=new Set([id]);let expanded=true;while(expanded){expanded=false;for(const x of state.tasks){if(!affected.has(x.id)&&x.deps.some(d=>affected.has(d))){affected.add(x.id);expanded=true}}}for(const x of state.tasks){if(affected.has(x.id))x.status=x.id===id?'ready':'blocked'}updateReadiness();state.releaseApproved=false;state.released=false;state.decisions.push({title:'G3 · Yêu cầu sửa task '+id,text:String(fd.get('comment')).trim()});persist();closeModal();setScreen('project');return}if(form.id==='add-role-form'){const id='custom'+Date.now();state.roles[id]={name:'Nhân sự mới',title:String(fd.get('title')).trim(),description:String(fd.get('description')).trim(),rule:String(fd.get('rule')).trim(),avatar:'observer',provider:'Claude',effort:'Medium'};persist();closeModal();render();toast('Đã thêm role mẫu; chưa gán vào đội.');return}if(form.id==='add-step-form'){const step={id:'custom-wf-'+Date.now(),name:String(fd.get('name')).trim(),role:String(fd.get('role')).trim(),type:fd.get('type')};const i=state.workflow.findIndex(w=>w.id==='wf8');state.workflow.splice(i<0?state.workflow.length:i,0,step);state.workflowDirty=true;persist();closeModal();render();return}if(form.id==='workflow-language-form'){const request=String(fd.get('request')).trim();const type=/báo cáo/i.test(request)?'report':/gate|cổng|duyệt/i.test(request)?'gate':null;if(!type){state.messages.secretary.push({from:'me',text:request},{from:'agent',text:'Đã ghi yêu cầu trong bản mẫu. Nội dung này cần AI thật làm rõ trước khi đổi workflow. Anh có thể dùng “Thêm bước” để cấu hình thủ công.'});closeModal();setScreen('secretary');chatClosed=false;render();persist();return}const candidate={id:'language-'+Date.now(),name:type==='report'?'Báo cáo bổ sung theo yêu cầu':'Gate bổ sung theo yêu cầu',role:type==='report'?'PM · tổng hợp kết quả':'Owner · quyết định bổ sung',type};openModal('Đề xuất thay đổi workflow mẫu',`<h3>Yêu cầu của anh</h3><p>${esc(request)}</p><div class="rule-diff"><div>Trước: Tích hợp → G3 nghiệm thu</div><div>Sau: Tích hợp → ${esc(candidate.name)} → G3 nghiệm thu</div></div><p class="inline-note">Đây là biến thể dựng sẵn của mockup. Bước mới giữ nguyên lời yêu cầu trong mô tả, cần tiếp tục làm rõ đầu ra và điều kiện đạt trước khi dùng thật.</p>`,`<button class="button" data-action="close-modal">Chưa áp dụng</button><button class="button primary" id="apply-language">Thêm vào bản nháp</button>`);document.querySelector('#apply-language').onclick=()=>{candidate.role+=' · '+request;const i=state.workflow.findIndex(w=>w.id==='wf8');state.workflow.splice(i<0?state.workflow.length:i,0,candidate);state.workflowDirty=true;persist();closeModal();setScreen('workflows');toast('Đã thêm bước vào bản nháp workflow.')};return}});
document.querySelector('#chat-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendChat(e.currentTarget.value)}});
document.querySelector('#modal-layer').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});
document.addEventListener('keydown',e=>{const layer=document.querySelector('#modal-layer');if(e.key==='Escape'){if(!layer.hidden)closeModal();else document.querySelector('.sidebar').classList.remove('mobile-open')}if(layer.hidden){if((e.key==='Enter'||e.key===' ')&&e.target.matches('.graph-task')){e.preventDefault();taskModal(e.target.dataset.task)}return}if(e.key==='Tab'){const items=[...document.querySelectorAll('#modal button:not([disabled]),#modal input,#modal textarea,#modal select,[id=modal]')].filter(x=>x.offsetParent!==null);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('dragstart',e=>{const n=e.target.closest('[data-wf]');if(!n)return;dragId=n.dataset.wf;e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move';n.classList.add('dragging')});
document.addEventListener('dragover',e=>{const row=e.target.closest('[data-wf-row]');if(row&&dragId){e.preventDefault();document.querySelectorAll('.workflow-row').forEach(x=>x.classList.toggle('dragover',x===row))}});
document.addEventListener('drop',e=>{const row=e.target.closest('[data-wf-row]');if(!row||!dragId)return;e.preventDefault();const from=state.workflow.findIndex(w=>w.id===dragId),to=state.workflow.findIndex(w=>w.id===row.dataset.wfRow);if(from>=0&&to>=0&&from!==to){const [w]=state.workflow.splice(from,1);state.workflow.splice(to,0,w);state.workflowDirty=true;render()}dragId=null});
document.addEventListener('dragend',()=>{dragId=null;document.querySelectorAll('.dragging,.dragover').forEach(x=>x.classList.remove('dragging','dragover'))});
try{document.documentElement.dataset.theme=localStorage.getItem('aio-prototype-theme')||'light'}catch{}
render();
